"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[248],{875:function(n,h,i){i.d(h,{Z:function(){return t}});let t=(0,i(9205).Z)("ChevronDown",[["path",{d:"m6 9 6 6 6-6",key:"qrunsl"}]])},8908:function(n,h,i){i.d(h,{ei:function(){return a},xx:function(){return t}});let t=[{term:"Lời Ch\xfaa / Ng\xf4i Lời",termLatin:"Verbum Dei / Logos",termGreek:"Λόγος (Logos)",termHebrew:"דָּבָר (Dabar)",termEnglish:"Word of God / Logos",pronunciation:"L\xf4-g\xf3t / Da-ba",category:"THEOLOGY",shortDefinition:"Mạc khải sống động của Thi\xean Ch\xfaa được thể hiện trọn vẹn nơi Đức Gi\xeasu Kit\xf4 - Ng\xf4i Lời Nhập Thể.",fullExplanation:'Trong truyền thống Do Th\xe1i, "Dabar" (Lời) kh\xf4ng chỉ l\xe0 ng\xf4n từ truyền đạt th\xf4ng tin, m\xe0 l\xe0 một thực tại sống động, năng động, c\xf3 quyền năng tạo dựng v\xe0 biến đổi. Khi Thi\xean Ch\xfaa ph\xe1n, điều Người n\xf3i liền trở th\xe0nh hiện thực (St 1,3: "Phải c\xf3 \xe1nh s\xe1ng! Liền c\xf3 \xe1nh s\xe1ng").\n\nTrong tiếng Hy Lạp, Logos (Λόγος) kh\xf4ng chỉ c\xf3 nghĩa l\xe0 "lời n\xf3i" m\xe0 c\xf2n bao h\xe0m: l\xfd tr\xed, trật tự vũ trụ, nguy\xean l\xfd cội rễ. Khi Th\xe1nh sử Gioan viết "Thoạt đầu đ\xe3 c\xf3 Ng\xf4i Lời" (Ga 1,1), ng\xe0i đồng thời đối thoại với cả truyền thống Do Th\xe1i (S\xe1ng thế) lẫn triết học Hy Lạp.\n\nĐỉnh cao mạc khải: Ng\xf4i Lời đ\xe3 mặc x\xe1c ph\xe0m (Ga 1,14) - Thi\xean Ch\xfaa vĩnh hằng trở th\xe0nh con người cụ thể trong lịch sử tại B\xealem. Từ đ\xf3, Kinh Th\xe1nh v\xe0 Truyền Thống T\xf4ng Truyền đều l\xe0 "Lời Ch\xfaa" dưới c\xe1c h\xecnh thức kh\xe1c nhau.',biblicalUsage:"Dabar xuất hiện hơn 1.400 lần trong Cựu Ước. Logos được Gioan d\xf9ng l\xe0m mở đầu Tin Mừng v\xe0 1 Gioan.",keyVerses:["Ga 1,1-3","Ga 1,14","Dt 4,12","2 Tm 3,16-17","Is 55,10-11"],cccLinks:[101,102,104,108,142],theologicalNote:"Dei Verbum (Hiến chế T\xedn l\xfd về Lời Ch\xfaa của Vatican II) x\xe1c định: Kinh Th\xe1nh v\xe0 Truyền Thống T\xf4ng Truyền h\xecnh th\xe0nh kho t\xe0ng Lời Ch\xfaa duy nhất được ủy th\xe1c cho Hội Th\xe1nh.",relatedTerms:["Mạc Khải","Nhập Thể","Linh Hứng Kinh Th\xe1nh","Truyền Thống T\xf4ng Truyền"]},{term:"Giao Ước",termLatin:"Foedus / Testamentum",termGreek:"Διαθήκη (Diatheke)",termHebrew:"בְּרִית (Berit)",termEnglish:"Covenant",category:"CONCEPT",shortDefinition:"Mối tương quan r\xe0ng buộc th\xe1nh thi\xeang giữa Thi\xean Ch\xfaa v\xe0 con người, nền tảng của to\xe0n bộ lịch sử cứu độ.",fullExplanation:'Berit trong truyền thống Do Th\xe1i l\xe0 h\xe0nh vi ph\xe1p l\xfd thi\xeang li\xeang nhất, tạo n\xean mối li\xean kết gia đ\xecnh giữa c\xe1c b\xean kh\xf4ng phải c\xf9ng huyết tộc. Kh\xe1c với hợp đồng th\xf4ng thường (trao đổi lợi \xedch), Giao Ước Thi\xean Ch\xfaa lu\xf4n xuất ph\xe1t từ s\xe1ng kiến nhưng kh\xf4ng của Người.\n\nChuỗi Giao Ước trong Kinh Th\xe1nh:\n1. Giao Ước với N\xf4-\xea (St 9): Dấu hiệu cầu vồng, Thi\xean Ch\xfaa kh\xf4ng ti\xeau diệt nh\xe2n loại.\n2. Giao Ước với \xc1p-ra-ham (St 15; 17): Lời hứa đất v\xe0 mi\xeau duệ đ\xf4ng như sao trời.\n3. Giao Ước Xi-nai qua M\xf4s\xea (Xh 19-24): Mười Điều Răn v\xe0 Luật Ph\xe1p.\n4. Giao Ước với Đav\xedt (2Sm 7): Lời hứa vương triều vĩnh cửu.\n5. Giao Ước Mới trong M\xe1u Đức Kit\xf4 (Lc 22,20; Dt 9,15): Ho\xe0n tất v\xe0 vượt qua mọi giao ước.\n\nĐức Gi\xeasu thiết lập Giao Ước Mới trong Bữa Tiệc Ly: "Ch\xe9n n\xe0y l\xe0 Giao Ước Mới k\xfd bằng m\xe1u Thầy" (Lc 22,20).',biblicalUsage:"Berit xuất hiện hơn 280 lần trong Cựu Ước, l\xe0 từ kho\xe1 trung t\xe2m của thần học Kinh Th\xe1nh.",keyVerses:["St 9,9","St 15,18","Xh 24,8","Gr 31,31-34","Lc 22,20","Dt 9,15"],cccLinks:[56,71,72,1961,1963],theologicalNote:"Lumen Gentium số 9 diễn tả Hội Th\xe1nh l\xe0 D\xe2n Giao Ước Mới. To\xe0n bộ Kinh Th\xe1nh được chia th\xe0nh Cựu Ước (Giao Ước Cũ) v\xe0 T\xe2n Ước (Giao Ước Mới) dựa tr\xean kh\xe1i niệm cốt l\xf5i n\xe0y.",relatedTerms:["Luật M\xf4s\xea","Mươi Điều Răn","Vượt Qua","B\xed T\xedch Th\xe1nh Thể","Hy Tế"]},{term:"Vượt Qua (Lễ Vượt Qua)",termLatin:"Pascha",termGreek:"Πάσχα (Pascha)",termHebrew:"פֶּסַח (Pesach)",termEnglish:"Passover / Pasch",pronunciation:"P\xea-sắc / P\xe1t-cha",category:"RITUAL",shortDefinition:"Lễ trọng đại nhất của Israel kỷ niệm cuộc giải ph\xf3ng khỏi Ai Cập, v\xe0 l\xe0 h\xecnh b\xf3ng ti\xean trưng hy tế cứu chuộc của Đức Kit\xf4.",fullExplanation:'Lễ Vượt Qua (Pesach) kỷ niệm đ\xeam Thi\xean Ch\xfaa "vượt qua" (ti\xeau diệt con trưởng Ai Cập) nhưng tha cho những nh\xe0 c\xf3 vết m\xe1u chi\xean tr\xean khung cửa (Xh 12). Chi\xean Vượt Qua phải ho\xe0n hảo, kh\xf4ng t\xec vết, m\xe1u được b\xf4i tr\xean cột v\xe0 thanh ngang cửa nh\xe0 (h\xecnh dạng thập gi\xe1 ti\xean trưng).\n\nĐức Gi\xeasu l\xe0 Chi\xean Vượt Qua đ\xedch thực:\n- Chết đ\xfang v\xe0o giờ s\xe1t tế chi\xean Vượt Qua tại Gi\xearusalem (Ga 19,14).\n- Kh\xf4ng một xương n\xe0o bị bẻ g\xe3y (Ga 19,33.36; Xh 12,46).\n- Th\xe1nh Phaol\xf4 tuy\xean bố r\xf5: "Đức Kit\xf4 đ\xe3 bị hiến tế: ch\xednh Người l\xe0 Chi\xean Vượt Qua của ch\xfang ta" (1Cr 5,7).\n- Th\xe1nh Gioan Tẩy Giả c\xf4ng bố: "Đ\xe2y Chi\xean Thi\xean Ch\xfaa, đ\xe2y Đấng x\xf3a tội trần gian" (Ga 1,29).',biblicalUsage:"Xh 12,1-14 m\xf4 tả lần đầu. Deuteronomy 16 quy định về lễ hằng năm. Tin Mừng Gioan đặt to\xe0n bộ Cuộc Khổ Nạn trong bối cảnh thần học Vượt Qua.",keyVerses:["Xh 12,1-14","1 Cr 5,7","Ga 1,29","Ga 19,36","Kh 5,6"],cccLinks:[571,608,613,1340,1363],theologicalNote:'Hội Th\xe1nh cử h\xe0nh mầu nhiệm Vượt Qua của Đức Kit\xf4 mỗi lần d\xe2ng Th\xe1nh Lễ. Đ\xeam Vọng Phục Sinh được gọi l\xe0 "Mẹ của tất cả c\xe1c đ\xeam canh thức" (Augustin\xf4).',relatedTerms:["Chi\xean Thi\xean Ch\xfaa","Xuất H\xe0nh","Hiến Tế","Phục Sinh","B\xed T\xedch Th\xe1nh Thể"]},{term:"Nước Thi\xean Ch\xfaa",termLatin:"Regnum Dei",termGreek:"Βασιλεία τοῦ Θεοῦ (Basileia tou Theou)",termHebrew:"מַלְכוּת יְהוָה (Malkut YHWH)",termEnglish:"Kingdom of God / Kingdom of Heaven",category:"THEOLOGY",shortDefinition:"Triều đại cai trị y\xeau thương của Thi\xean Ch\xfaa được Đức Gi\xeasu c\xf4ng bố v\xe0 khai mở trong lịch sử, hướng về sự ho\xe0n tất vi\xean m\xe3n trong c\xe1nh chung.",fullExplanation:'"Nước Thi\xean Ch\xfaa" l\xe0 chủ đề trung t\xe2m của to\xe0n bộ c\xf4ng cuộc rao giảng của Đức Gi\xeasu (Mc 1,15). Đ\xe2y kh\xf4ng phải l\xe0 một l\xe3nh thổ địa l\xfd hay một cơ cấu ch\xednh trị, m\xe0 l\xe0 triều đại t\xecnh y\xeau, c\xf4ng l\xfd v\xe0 b\xecnh an m\xe0 Thi\xean Ch\xfaa đang thực hiện trong lịch sử qua Đức Kit\xf4 v\xe0 Thần Kh\xed của Người.\n\nBa chiều k\xedch của Nước Thi\xean Ch\xfaa:\n1. Đ\xe3 đến (Already): Nước đ\xe3 c\xf3 mặt trong Đức Gi\xeasu Kit\xf4 - qua c\xe1c ph\xe9p lạ chữa bệnh, trừ quỷ, tha tội.\n2. Đang đến (Coming): Nước đang triển khai qua Hội Th\xe1nh v\xe0 c\xe1c b\xed t\xedch.\n3. Chưa đến trọn vẹn (Not yet): Sẽ được ho\xe0n tất vi\xean m\xe3n khi Đức Kit\xf4 trở lại trong vinh quang.\n\nT\xe1m Mối Ph\xfac (Mt 5,3-12) l\xe0 Hiến Ph\xe1p của Nước Thi\xean Ch\xfaa, m\xf4 tả diện mạo c\xf4ng d\xe2n đ\xedch thực của Nước ấy.',biblicalUsage:'Xuất hiện hơn 100 lần trong Tin Mừng Nhất L\xe3m. M\xe1tth\xeau d\xf9ng "Nước Trời" (Basileia ton ouranon) để tr\xe1nh d\xf9ng danh Thi\xean Ch\xfaa theo tập tục Do Th\xe1i.',keyVerses:["Mc 1,15","Mt 6,33","Lc 17,20-21","Mt 13,44-46","Ga 18,36"],cccLinks:[541,546,567,671,2816],theologicalNote:'Lumen Gentium số 5 x\xe1c định Hội Th\xe1nh kh\xf4ng đồng nhất với Nước Thi\xean Ch\xfaa, nhưng l\xe0 "mầm mống v\xe0 khởi đầu của Nước ấy tr\xean trần gian".',relatedTerms:["Tin Mừng","M\xf4n Đệ","Eschatology","Hội Th\xe1nh","B\xe1t Ph\xfac"]},{term:"\xc2n Sủng",termLatin:"Gratia",termGreek:"Χάρις (Charis)",termHebrew:"חֵן (Chen) / חֶסֶד (Hesed)",termEnglish:"Grace",category:"THEOLOGY",shortDefinition:"Sự trợ gi\xfap nhưng kh\xf4ng của Thi\xean Ch\xfaa ban cho con người để cứu độ v\xe0 th\xe1nh h\xf3a, ho\xe0n to\xe0n kh\xf4ng phải do c\xf4ng trạng.",fullExplanation:'Charis trong tiếng Hy Lạp Koine c\xf3 nghĩa gốc l\xe0 "vẻ đẹp, sự duy\xean d\xe1ng, m\xf3n qu\xe0". Trong T\xe2n Ước, từ n\xe0y mang \xfd nghĩa thần học độc đ\xe1o: sự ưu \xe1i ho\xe0n to\xe0n nhưng kh\xf4ng v\xe0 ban ph\xe1t tự do của Thi\xean Ch\xfaa.\n\nC\xe1c loại \xe2n sủng:\n1. \xc2n sủng hiện sủng (Actual Grace): Sự trợ gi\xfap cụ thể, tức thời của Thi\xean Ch\xfaa trong mỗi h\xe0nh vi cụ thể.\n2. \xc2n sủng thường sủng / \xe2n sủng th\xe1nh h\xf3a (Sanctifying Grace): Sự tham dự v\xe0o sự sống thần linh của Thi\xean Ch\xfaa, được ban qua Ph\xe9p Rửa.\n3. \xc2n sủng b\xed t\xedch: \xc2n sủng đặc th\xf9 qua từng b\xed t\xedch.\n4. Đặc sủng (Charismata): Hồng \xe2n đặc biệt cho sứ vụ trong Hội Th\xe1nh.\n\nTh\xe1nh Phaol\xf4 tuy\xean bố: "Ch\xednh do \xe2n sủng v\xe0 nhờ l\xf2ng tin m\xe0 anh em được cứu độ: đ\xe2y kh\xf4ng phải bởi sức anh em, m\xe0 l\xe0 \xe2n huệ của Thi\xean Ch\xfaa" (Ep 2,8).',biblicalUsage:"Charis xuất hiện 155 lần trong T\xe2n Ước. Phaol\xf4 d\xf9ng nhiều nhất (100 lần) để diễn tả cốt l\xf5i Tin Mừng.",keyVerses:["Ep 2,8-9","Rm 3,24","Rm 5,15","Ga 1,14","2 Cr 12,9"],cccLinks:[1996,1997,1999,2e3,2024],theologicalNote:"Hội đồng Trent\xf4 (1547) định t\xedn: \xc2n sủng c\xf4ng ch\xednh h\xf3a kh\xf4ng chỉ l\xe0 sự tha thứ tội lỗi m\xe0 c\xf2n l\xe0 sự đổi mới nội t\xe2m thực sự, tham dự v\xe0o bản t\xednh Thi\xean Ch\xfaa (2Pr 1,4).",relatedTerms:["C\xf4ng Ch\xednh H\xf3a","Th\xe1nh H\xf3a","Ph\xe9p Rửa","Ơn Cứu Độ","Đức Tin"]},{term:"Đấng M\xeasia / Kit\xf4",termLatin:"Christus / Messias",termGreek:"Χριστός (Christos)",termHebrew:"מָשִׁיחַ (Mashiach)",termEnglish:"Messiah / Christ",pronunciation:"Ma-si-ắc / Chri-st\xf3s",category:"THEOLOGY",shortDefinition:"Người được xức dầu th\xe1nh, Đấng Cứu Thế được Thi\xean Ch\xfaa ph\xe1i đến để giải ph\xf3ng d\xe2n Người v\xe0 thiết lập Vương Triều Thi\xean Ch\xfaa.",fullExplanation:'Mashiach (tiếng Do Th\xe1i) v\xe0 Christos (tiếng Hy Lạp) đều c\xf3 nghĩa l\xe0 "Người được xức dầu". Trong Cựu Ước, ba loại nh\xe2n vật được xức dầu th\xe1nh: vua (1Sm 10,1), tư tế (Xh 29,7), v\xe0 ng\xf4n sứ (1V 19,16). Đ\xe2y l\xe0 ba sứ vụ m\xe0 Đức Gi\xeasu Kit\xf4 thực hiện trọn vẹn v\xe0 ho\xe0n hảo.\n\nLịch sử niềm mong đợi M\xeasia:\n- Lời hứa đầu ti\xean (Protoevangelium): St 3,15 - mi\xeau duệ người nữ.\n- Lời hứa với \xc1p-ra-ham (St 12,3): mu\xf4n d\xe2n được ch\xfac ph\xfac qua mi\xeau duệ \xf4ng.\n- Lời hứa với Đav\xedt (2Sm 7,12-16): vương triều vĩnh cửu.\n- Người T\xf4i Trung đau khổ (Is 52-53): đau khổ cứu chuộc.\n- Con Người trong Đa-ni-en 7,13.\n\nTuy\xean xưng đức tin của Ph\xear\xf4 tại X\xea-da-r\xea Phi-l\xedp: "Thầy l\xe0 Đấng Kit\xf4, Con Thi\xean Ch\xfaa hằng sống" (Mt 16,16) l\xe0 đỉnh cao của Tin Mừng Nhất L\xe3m.',biblicalUsage:"Mashiach xuất hiện 39 lần trong Cựu Ước. Christos xuất hiện 529 lần trong T\xe2n Ước.",keyVerses:["Is 61,1","Mt 16,16","Lc 4,18","Ga 1,41","Cv 2,36"],cccLinks:[436,437,453,711,712],theologicalNote:"Gi\xe1o l\xfd C\xf4ng gi\xe1o nhấn mạnh: Đức Gi\xeasu l\xe0 Đấng M\xeasia kh\xf4ng phải theo kiểu ch\xednh trị m\xe0 người Do Th\xe1i tr\xf4ng đợi, m\xe0 l\xe0 Đấng M\xeasia khổ nạn v\xe0 phục sinh, cứu độ bằng t\xecnh y\xeau tự hiến.",relatedTerms:["Ti\xean Trưng","Người T\xf4i Trung","Nhập Thể","Phục Sinh","Nước Thi\xean Ch\xfaa"]},{term:"Gi\xe1o Hội / Hội Th\xe1nh",termLatin:"Ecclesia",termGreek:"Ἐκκλησία (Ekklesia)",termHebrew:"קָהָל (Qahal)",termEnglish:"Church",pronunciation:"Ek-kle-si-a",category:"THEOLOGY",shortDefinition:"Cộng đo\xe0n những người được Thi\xean Ch\xfaa triệu tập nh\xe2n danh Đức Kit\xf4, nối d\xe0i mầu nhiệm Nhập Thể trong lịch sử.",fullExplanation:'Ekklesia (tiếng Hy Lạp) c\xf3 nghĩa gốc l\xe0 "hội đồng c\xf4ng d\xe2n được triệu tập" - những người được k\xeau gọi ra khỏi (ek-kalein) cuộc sống tối tăm v\xe0 tội lỗi. Tương đương với Qahal trong Cựu Ước - đại hội d\xe2n Ch\xfaa tại Sinai.\n\nHội Th\xe1nh trong mầu nhiệm (theo Lumen Gentium):\n1. D\xe2n Thi\xean Ch\xfaa: D\xe2n Giao Ước Mới, kế thừa v\xe0 vượt qua Israel.\n2. Th\xe2n M\xecnh Đức Kit\xf4: Đức Kit\xf4 l\xe0 Đầu, t\xedn hữu l\xe0 chi thể.\n3. Đền Thờ Ch\xfaa Th\xe1nh Thần: Nơi Thần Kh\xed ngự trị v\xe0 th\xe1nh h\xf3a.\n4. Hiền Th\xea của Đức Kit\xf4: Mối tương quan y\xeau thương h\xf4n nh\xe2n thần linh.\n\nBốn đặc t\xednh cốt l\xf5i (Kinh Tin K\xednh): Duy Nhất, Th\xe1nh Thiện, C\xf4ng Gi\xe1o (Phổ Qu\xe1t), T\xf4ng Truyền.\n\n"Hội Th\xe1nh của Đức Kit\xf4 tồn tại đầy đủ trong Hội Th\xe1nh C\xf4ng gi\xe1o, do Đấng Kế Vị Ph\xear\xf4 v\xe0 c\xe1c Gi\xe1m Mục hiệp th\xf4ng với ng\xe0i điều h\xe0nh" (Lumen Gentium 8).',biblicalUsage:"Ekklesia xuất hiện 114 lần trong T\xe2n Ước. Mt 16,18 l\xe0 lần đầu Ch\xfaa Gi\xeasu d\xf9ng từ n\xe0y về cộng đo\xe0n của Người.",keyVerses:["Mt 16,18","1 Cr 12,27","Ep 1,22-23","Cl 1,18","Kh 19,7"],cccLinks:[751,752,759,771,781],theologicalNote:"Lumen Gentium (1964) l\xe0 Hiến chế T\xedn l\xfd nền tảng về Hội Th\xe1nh của C\xf4ng đồng Vatican II. Gaudium et Spes bổ sung chiều k\xedch Hội Th\xe1nh trong thế giới hiện đại.",relatedTerms:["Ph\xe9p Rửa","B\xed T\xedch","Gi\xe1m Mục","Gi\xe1o Ho\xe0ng","T\xf4ng Truyền","Hiệp Th\xf4ng"]},{term:"Đức Tin",termLatin:"Fides",termGreek:"Πίστις (Pistis)",termHebrew:"אֱמוּנָה (Emunah)",termEnglish:"Faith",category:"THEOLOGY",shortDefinition:"Sự đ\xe1p trả tự do v\xe0 trọn vẹn của con người trước Thi\xean Ch\xfaa tự mạc khải - gồm cả tr\xed tuệ, \xfd ch\xed v\xe0 h\xe0nh động.",fullExplanation:'Emunah (tiếng Do Th\xe1i) c\xf3 gốc từ "aman" - vững chắc, ki\xean định, đ\xe1ng tin. Đức tin kh\xf4ng phải chủ yếu l\xe0 chấp nhận c\xe1c gi\xe1o thuyết trừu tượng, m\xe0 l\xe0 sự t\xedn th\xe1c c\xe1 nh\xe2n to\xe0n vẹn v\xe0o Thi\xean Ch\xfaa trung t\xedn.\n\nPistis (tiếng Hy Lạp) bao gồm:\n1. Fides quae (đức tin về nội dung): Những ch\xe2n l\xfd được tin.\n2. Fides qua (đức tin như h\xe0nh vi): H\xe0nh vi tin tưởng bản th\xe2n.\n3. Fides ex auditu: Đức tin đến từ việc lắng nghe Lời Ch\xfaa (Rm 10,17).\n\nĐức tin theo Th\xe1nh Phaol\xf4:\n- \xc1p-ra-ham l\xe0 cha của kẻ tin (Rm 4): đức tin trước Luật Ph\xe1p.\n- "Người c\xf4ng ch\xednh sẽ sống nhờ đức tin" (Rm 1,17; Hb 2,4).\n- Bộ ba đức tin - đức cậy - đức mến (1Cr 13,13).\n\nTh\xe1nh Giac\xf4b\xea bổ sung: Đức tin kh\xf4ng c\xf3 h\xe0nh động th\xec đức tin ấy chết (Gc 2,17) - kh\xf4ng m\xe2u thuẫn Phaol\xf4 m\xe0 bổ sung: đức tin đ\xedch thực sinh hoa tr\xe1i h\xe0nh động.',biblicalUsage:'Pistis xuất hiện 243 lần trong T\xe2n Ước. Thư Hipri chương 11 l\xe0 "H\xe0nh lang của c\xe1c anh h\xf9ng đức tin" liệt k\xea gương s\xe1ng Cựu Ước.',keyVerses:["Dt 11,1","Rm 1,17","Rm 10,17","Gc 2,17","Ga 20,29"],cccLinks:[142,150,153,162,1814],theologicalNote:"Hội đồng Vatican I (Dei Filius, 1870) v\xe0 Vatican II (Dei Verbum, 1965) đều khẳng định: Đức tin l\xe0 h\xe0nh vi l\xfd tr\xed v\xe0 \xfd ch\xed tự do, kh\xf4ng m\xe2u thuẫn với l\xfd tr\xed m\xe0 được l\xfd tr\xed chuẩn bị v\xe0 bổ sung.",relatedTerms:["Đức Cậy","Đức Mến","Mạc Khải","Ơn Cứu Độ","Ph\xe9p Rửa"]},{term:"Ơn Cứu Độ / Cứu Chuộc",termLatin:"Salvatio / Redemptio",termGreek:"Σωτηρία (Soteria)",termHebrew:"יְשׁוּעָה (Yeshuah)",termEnglish:"Salvation / Redemption",pronunciation:"So-te-ri-a / Ye-shu-a",category:"THEOLOGY",shortDefinition:"H\xe0nh động Thi\xean Ch\xfaa giải ph\xf3ng con người khỏi tội lỗi, c\xe1i chết v\xe0 mọi quyền lực xấu, phục hồi tương quan với Người v\xe0 ban sự sống đời đời.",fullExplanation:'Yeshuah (tiếng Do Th\xe1i) nghĩa l\xe0 "giải ph\xf3ng, cứu tho\xe1t" - l\xe0 gốc của t\xean "Gi\xeasu" (Yeshua = Thi\xean Ch\xfaa cứu độ). Thi\xean thần truyền cho Giuse: "\xd4ng phải đặt t\xean con trẻ l\xe0 Gi\xeasu, v\xec ch\xednh Người sẽ cứu d\xe2n Người khỏi tội lỗi của họ" (Mt 1,21).\n\nPh\xe2n biệt c\xe1c kh\xe1i niệm:\n1. Cứu Độ (Salvation): Kh\xe1i niệm rộng bao gồm to\xe0n bộ kế hoạch Thi\xean Ch\xfaa phục hồi con người.\n2. Cứu Chuộc (Redemption): Nhấn mạnh \xfd nghĩa "mua lại, giải ph\xf3ng khỏi n\xf4 lệ" - Đức Kit\xf4 trả gi\xe1 bằng M\xe1u (1Pr 1,18-19).\n3. H\xf2a Giải (Reconciliation): Phục hồi mối tương quan bị đứt vỡ do tội (2Cr 5,18-19).\n4. C\xf4ng Ch\xednh H\xf3a (Justification): Được tuy\xean bố c\xf4ng ch\xednh trước Thi\xean Ch\xfaa nhờ \xe2n sủng v\xe0 đức tin (Rm 3,24).\n\nĐức Gi\xeasu cứu độ bằng to\xe0n bộ mầu nhiệm Nhập Thể, Cuộc Đời, Khổ Nạn, Tử Nạn v\xe0 Phục Sinh - kh\xf4ng chỉ ri\xeang Thập Gi\xe1.',biblicalUsage:"Yeshuah xuất hiện 78 lần trong Cựu Ước. Soteria xuất hiện 46 lần trong T\xe2n Ước.",keyVerses:["Mt 1,21","Ga 3,16","Rm 5,8","1 Tm 2,4","Cv 4,12"],cccLinks:[430,601,614,616,1026],theologicalNote:"Hội Th\xe1nh C\xf4ng gi\xe1o khẳng định: Đức Kit\xf4 l\xe0 Đấng Trung Gian duy nhất (1Tm 2,5), nhưng ơn cứu độ c\xf3 thể đến với mọi người thiện ch\xed qua Hội Th\xe1nh v\xe0 Mầu Nhiệm Vượt Qua, d\xf9 họ kh\xf4ng biết Đức Kit\xf4 c\xe1ch tường minh (Lumen Gentium 16).",relatedTerms:["Nhập Thể","Khổ Nạn","Phục Sinh","\xc2n Sủng","Ph\xe9p Rửa"]},{term:"Th\xe1nh Thần / Thần Kh\xed",termLatin:"Spiritus Sanctus",termGreek:"Ἅγιον Πνεῦμα (Hagion Pneuma)",termHebrew:"רוּחַ הַקֹּדֶשׁ (Ruach Ha-Kodesh)",termEnglish:"Holy Spirit",category:"THEOLOGY",shortDefinition:'Ng\xf4i Ba Thi\xean Ch\xfaa, "Ch\xfaa v\xe0 l\xe0 Đấng ban sự sống", Thầy dạy v\xe0 Đấng Bảo Trợ của Hội Th\xe1nh.',fullExplanation:'Ruach (tiếng Do Th\xe1i) c\xf3 nghĩa đa tầng: gi\xf3, hơi thở, thần kh\xed, tinh thần. Pneuma (tiếng Hy Lạp) tương tự: hơi thở, gi\xf3, linh hồn, thần kh\xed.\n\nCh\xfaa Th\xe1nh Thần trong Cựu Ước:\n- Thần Kh\xed Thi\xean Ch\xfaa bay lượn tr\xean mặt nước (St 1,2).\n- Thần Kh\xed ngự xuống tr\xean c\xe1c ng\xf4n sứ, quan x\xe9t.\n- Lời hứa tu\xf4n đổ Thần Kh\xed tr\xean mọi x\xe1c thịt (Ge 3,1-2).\n\nCh\xfaa Th\xe1nh Thần trong T\xe2n Ước:\n- Thụ Thai Ch\xfaa Gi\xeasu (Lc 1,35).\n- Ph\xe9p Rửa của Ch\xfaa Gi\xeasu (Mt 3,16).\n- Lễ Hiện Xuống - ng\xe0y sinh nhật Hội Th\xe1nh (Cv 2,1-13).\n- Thầy dạy v\xe0 Đấng Nhắc Nhở (Ga 14,26).\n- Đấng Bảo Trợ / Đấng An Ủi (Parakletos - Ga 14,16).\n\nKinh Tin K\xednh Nic\xeaa-Constantinople (381) tuy\xean t\xedn: Ch\xfaa Th\xe1nh Thần l\xe0 "Ch\xfaa v\xe0 l\xe0 Đấng ban sự sống, Người bởi Ch\xfaa Cha v\xe0 Ch\xfaa Con m\xe0 ra, được phụng thờ v\xe0 t\xf4n vinh c\xf9ng với Ch\xfaa Cha v\xe0 Ch\xfaa Con".',biblicalUsage:"Ruach Ha-Kodesh trong Cựu Ước. Hagion Pneuma xuất hiện 90 lần trong T\xe2n Ước, đặc biệt d\xe0y đặc trong Gioan 14-16 v\xe0 C\xf4ng Vụ T\xf4ng Đồ.",keyVerses:["St 1,2","Lc 1,35","Ga 14,16-17","Ga 14,26","Cv 2,4","Rm 8,26"],cccLinks:[687,703,729,742,1830],theologicalNote:"Gi\xe1o l\xfd C\xf4ng gi\xe1o nhấn mạnh Ch\xfaa Th\xe1nh Thần kh\xf4ng chỉ h\xe0nh động trong Hội Th\xe1nh m\xe0 c\xf2n hoạt động trong to\xe0n thế giới, chuẩn bị v\xe0 dẫn đưa mọi người về với Đức Kit\xf4.",relatedTerms:["Thi\xean Ch\xfaa Ba Ng\xf4i","Ph\xe9p Rửa","Th\xeam Sức","Đặc Sủng","Lễ Hiện Xuống"]}],a=[{reference:"Ga 1,1",bookId:"john",chapter:1,verse:1,translations:[{translationId:"vi-gkpv",text:"Thoạt đầu đ\xe3 c\xf3 Ng\xf4i Lời. Ng\xf4i Lời vẫn hướng về Thi\xean Ch\xfaa, v\xe0 Ng\xf4i Lời l\xe0 Thi\xean Ch\xfaa.",language:"Tiếng Việt (GKPV)"},{translationId:"la-vulgate",text:"In principio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum.",language:"Latinh (Vulgata)"},{translationId:"gr-na28",text:"Ἐν ἀρχῇ ἦν ὁ λόγος, καὶ ὁ λόγος ἦν πρὸς τὸν θεόν, καὶ θεὸς ἦν ὁ λόγος.",language:"Hy Lạp (NA28)"}],keyWords:[{term:"ἐν ἀρχῇ",language:"Hy Lạp",transliteration:"en arche",meaning:'Thoạt đầu / Trong nguy\xean l\xfd / Trong khởi nguy\xean — phản chiếu St 1,1 tiếng Do Th\xe1i "Bereshit"'},{term:"λόγος",language:"Hy Lạp",transliteration:"Logos",meaning:"Lời / Ng\xf4i Lời / L\xfd tr\xed vũ trụ — vừa đối thoại với triết học Hy Lạp vừa l\xe0 Dabar tiếng Do Th\xe1i"},{term:"ἦν πρὸς",language:"Hy Lạp",transliteration:"en pros",meaning:'Hướng về / Ở c\xf9ng — pros kh\xf4ng chỉ l\xe0 "b\xean cạnh" m\xe0 l\xe0 "mặt đối mặt, tương quan mật thiết"'}],cccLinks:[241,242,291],exegeticalNote:"Ba c\xe2u ngắn với cấu tr\xfac leo thang (chiasmus): Logos tồn tại trước s\xe1ng tạo → hiệp th\xf4ng với Thi\xean Ch\xfaa → đồng bản t\xednh với Thi\xean Ch\xfaa. Ba tuy\xean bố n\xe0y l\xe0m nền tảng cho Học thuyết Thi\xean Ch\xfaa Ba Ng\xf4i."},{reference:"Mt 16,18",bookId:"matt",chapter:16,verse:18,translations:[{translationId:"vi-gkpv",text:"C\xf2n Thầy, Thầy bảo cho anh biết: anh l\xe0 Ph\xear\xf4, nghĩa l\xe0 Tảng Đ\xe1, tr\xean tảng đ\xe1 n\xe0y, Thầy sẽ x\xe2y Hội Th\xe1nh của Thầy, v\xe0 quyền lực tử thần sẽ kh\xf4ng thắng nổi.",language:"Tiếng Việt (GKPV)"},{translationId:"la-vulgate",text:"Et ego dico tibi quia tu es Petrus et super hanc petram aedificabo ecclesiam meam et portae inferi non praevalebunt adversum eam.",language:"Latinh (Vulgata)"},{translationId:"gr-na28",text:"κἀγὼ δέ σοι λέγω ὅτι σὺ εἶ Πέτρος, καὶ ἐπὶ ταύτῃ τῇ πέτρᾳ οἰκοδομήσω μου τὴν ἐκκλησίαν, καὶ πύλαι ᾅδου οὐ κατισχύσουσιν αὐτῆς.",language:"Hy Lạp (NA28)"}],keyWords:[{term:"Πέτρος / πέτρᾳ",language:"Hy Lạp",transliteration:"Petros / petra",meaning:'Ph\xear\xf4 (t\xean ri\xeang nam) / Tảng Đ\xe1 (nền tảng vĩ đại). Trong tiếng Aram m\xe0 Ch\xfaa Gi\xeasu d\xf9ng: Kepha = tảng đ\xe1, kh\xf4ng ph\xe2n biệt. Gioan 1,42 x\xe1c nhận: "Anh sẽ được gọi l\xe0 K\xeapha"'},{term:"ἐκκλησίαν",language:"Hy Lạp",transliteration:"ekklesian",meaning:"Hội Th\xe1nh — cộng đo\xe0n được triệu tập. Đ\xe2y l\xe0 lần đầu ti\xean Ch\xfaa Gi\xeasu d\xf9ng từ n\xe0y về cộng đo\xe0n của Người"},{term:"πύλαι ᾅδου",language:"Hy Lạp",transliteration:"pylai hadou",meaning:"Cửa địa ngục / Cổng \xe2m phủ — kh\xf4ng phải \xe1c thần tấn c\xf4ng, m\xe0 l\xe0 sức mạnh c\xe1i chết kh\xf4ng thể ti\xeau diệt Hội Th\xe1nh"}],cccLinks:[552,553,881,882],exegeticalNote:"Ch\xfaa Gi\xeasu đổi t\xean Simon th\xe0nh Ph\xear\xf4 — h\xe0nh động mang tầm thi\xeang li\xeang (như Abraham, Israel). Trao quyền Ch\xeca Kh\xf3a (Is 22,22) đặt Ph\xear\xf4 v\xe0o vai tr\xf2 Tể Tướng Nh\xe0 Vua Đav\xedt, nền tảng lịch sử của chức Gi\xe1o Ho\xe0ng."},{reference:"Rm 8,38-39",bookId:"rom",chapter:8,verse:38,translations:[{translationId:"vi-gkpv",text:"V\xec t\xf4i th\xe2m t\xedn rằng sự chết hay sự sống, d\xf9 thi\xean thần hay thi\xean phủ, d\xf9 hiện tại hay tương lai, d\xf9 quyền năng, d\xf9 chiều cao hay chiều s\xe2u, hay bất cứ tạo vật n\xe0o kh\xe1c, kh\xf4ng c\xf3 g\xec t\xe1ch được ch\xfang ta ra khỏi t\xecnh y\xeau của Thi\xean Ch\xfaa thể hiện nơi Đức Kit\xf4 Gi\xeasu, Ch\xfaa ch\xfang ta.",language:"Tiếng Việt (GKPV)"},{translationId:"la-vulgate",text:"Certus sum enim quia neque mors neque vita neque angeli neque principatus neque praesentia neque futura neque virtutes neque altitudo neque profundum neque creatura alia aliqua poterit nos separare a caritate Dei, quae est in Christo Iesu Domino nostro.",language:"Latinh (Vulgata)"},{translationId:"gr-na28",text:"πέπεισμαι γὰρ ὅτι οὔτε θάνατος οὔτε ζωή... οὔτε τις κτίσις ἑτέρα δυνήσεται ἡμᾶς χωρίσαι ἀπὸ τῆς ἀγάπης τοῦ θεοῦ τῆς ἐν Χριστῷ Ἰησοῦ τῷ κυρίῳ ἡμῶν.",language:"Hy Lạp (NA28)"}],keyWords:[{term:"ἀγάπης",language:"Hy Lạp",transliteration:"agapes",meaning:"T\xecnh y\xeau (Agape) — t\xecnh y\xeau v\xf4 điều kiện, tự hiến, kh\xf4ng phải eros (t\xecnh luyến \xe1i) hay philia (t\xecnh bạn). Từ Kit\xf4 gi\xe1o đặc th\xf9 cho t\xecnh y\xeau Thi\xean Ch\xfaa."},{term:"χωρίσαι",language:"Hy Lạp",transliteration:"chorisai",meaning:"T\xe1ch ra / Ly c\xe1ch — kh\xf4ng một thực tại n\xe0o trong vũ trụ c\xf3 đủ quyền năng ngăn c\xe1ch t\xedn hữu khỏi t\xecnh y\xeau Thi\xean Ch\xfaa trong Đức Kit\xf4."}],cccLinks:[308,1821,1994],exegeticalNote:"Đ\xe2y l\xe0 đỉnh cao của Thư R\xf4ma chương 8 — th\xe1nh ca t\xecnh y\xeau của Phaol\xf4. Liệt k\xea 10 thực tại vũ trụ kh\xf4ng thể ph\xe1 vỡ giao ước Thi\xean Ch\xfaa-con người trong Đức Kit\xf4. Cấu tr\xfac văn chương đối ngẫu (antithesis) cực kỳ tinh tế."},{reference:"St 1,1",bookId:"gen",chapter:1,verse:1,translations:[{translationId:"vi-gkpv",text:"Thoạt đầu, Thi\xean Ch\xfaa s\xe1ng tạo trời v\xe0 đất.",language:"Tiếng Việt (GKPV)"},{translationId:"la-vulgate",text:"In principio creavit Deus caelum et terram.",language:"Latinh (Vulgata)"},{translationId:"hb-masoretic",text:"בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ",language:"Do Th\xe1i (MT)"},{translationId:"gr-lxx",text:"Ἐν ἀρχῇ ἐποίησεν ὁ θεὸς τὸν οὐρανὸν καὶ τὴν γῆν.",language:"Hy Lạp (LXX)"}],keyWords:[{term:"בְּרֵאשִׁית",language:"Do Th\xe1i",transliteration:"Bereshit",meaning:"Thoạt đầu / Trong nguy\xean l\xfd — kh\xf4ng chỉ l\xe0 điểm thời gian m\xe0 l\xe0 bản thể luận: Thi\xean Ch\xfaa l\xe0 nguy\xean l\xfd cội rễ của tất cả"},{term:"בָּרָא",language:"Do Th\xe1i",transliteration:"Bara",meaning:"S\xe1ng tạo — động từ độc quyền d\xe0nh cho Thi\xean Ch\xfaa. Kh\xf4ng bao giờ c\xf3 vật liệu l\xe0m t\xe2n ngữ → Creatio ex nihilo (s\xe1ng tạo từ hư v\xf4)"},{term:"אֱלֹהִים",language:"Do Th\xe1i",transliteration:"Elohim",meaning:"Thi\xean Ch\xfaa (số nhiều trang nghi\xeam) — số nhiều nhưng động từ số \xedt, thể hiện phẩm gi\xe1 v\xe0 sự sung m\xe3n thần linh. C\xe1c Gi\xe1o phụ thấy dấu hiệu Ba Ng\xf4i"}],cccLinks:[279,280,290,296],exegeticalNote:"C\xe2u ngắn nhưng l\xe0 tuy\xean ng\xf4n thần học c\xe1ch mạng: b\xe1c bỏ mọi dạng nhị nguy\xean thần (thần thiện/thần \xe1c), đa thần (nhiều thần s\xe1ng tạo) v\xe0 phiếm thần (vũ trụ ch\xednh l\xe0 Thi\xean Ch\xfaa). Chỉ c\xf3 MỘT Thi\xean Ch\xfaa, Đấng s\xe1ng tạo TẤT CẢ từ HƯ V\xd4."},{reference:"Lc 1,28",bookId:"luke",chapter:1,verse:28,translations:[{translationId:"vi-gkpv",text:"B\xe0 được đầy \xe2n sủng, Đức Ch\xfaa Trời ở c\xf9ng b\xe0.",language:"Tiếng Việt (GKPV)"},{translationId:"la-vulgate",text:"Ave, gratia plena, Dominus tecum, benedicta tu in mulieribus.",language:"Latinh (Vulgata)"},{translationId:"gr-na28",text:"χαῖρε, κεχαριτωμένη, ὁ κύριος μετά σου.",language:"Hy Lạp (NA28)"}],keyWords:[{term:"κεχαριτωμένη",language:"Hy Lạp",transliteration:"kecharitomene",meaning:"Đ\xe3 được \xe2n sủng trọn vẹn — thể ho\xe0n th\xe0nh thụ động (perfect passive participle): \xe2n sủng ho\xe0n tất từ trước, dấu hiệu của t\xedn điều V\xf4 Nhiễm Nguy\xean Tội"},{term:"χαῖρε",language:"Hy Lạp",transliteration:"chaire",meaning:'Vui l\xean / K\xednh ch\xe0o — kh\xf4ng phải chỉ "xin ch\xe0o" th\xf4ng thường m\xe0 l\xe0 lời loan b\xe1o vui mừng cứu độ, như c\xe1c ng\xf4n sứ Zacaria 9,9 v\xe0 Gi\xf4-en 2,21'}],cccLinks:[490,491,492,722],exegeticalNote:'T\xean thi\xean thần d\xf9ng thay cho t\xean ri\xeang Maria: "Kecharitomene" = "Người được \xe2n sủng trọn vẹn". Hội Th\xe1nh dựa v\xe0o từ n\xe0y (thể ho\xe0n th\xe0nh Hy Lạp) để x\xe1c nhận Đức Maria đ\xe3 được th\xe1nh h\xf3a v\xe0 g\xecn giữ khỏi tội từ trước khi thụ thai — nền tảng ng\xf4n ngữ của t\xedn điều V\xf4 Nhiễm Nguy\xean Tội (1854).'}]}}]);